import { useEffect, useState, useCallback } from "react";

import { getApiBase } from "../api/base";
import { authFetch } from "../api/authFetch";
const API = getApiBase() + "/backend";

const AdminTransactions = () => {
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [role, setRole] = useState(null);
  const [pharmacies, setPharmacies] = useState([]);
  const [pharmacyId, setPharmacyId] = useState("");

  useEffect(() => {
    setRole(localStorage.getItem("role"));
  }, []);

  useEffect(() => {
    const fetchPharmacies = async () => {
      if (role !== "super_admin") return;
      try {
        const res = await authFetch(`${API}/superadmin/pharmacies`);
        const data = await res.json();
        if (res.ok && data.success && Array.isArray(data.pharmacies)) {
          setPharmacies(data.pharmacies);
          if (!pharmacyId && data.pharmacies[0]?._id)
            setPharmacyId(data.pharmacies[0]._id);
        }
      } catch {
        /* ignore */
      }
    };
    fetchPharmacies();
  }, [role, pharmacyId]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const qs = new URLSearchParams({ limit: "500" });
      if (role === "super_admin" && pharmacyId)
        qs.set("pharmacyId", pharmacyId);
      const res = await authFetch(`${API}/inventory/ledger?${qs.toString()}`);
      const data = await res.json();
      if (res.ok && data.success) setEntries(data.entries || []);
    } catch (err) {
      console.error("Failed to load transactions", err);
    } finally {
      setLoading(false);
    }
  }, [role, pharmacyId]);

  useEffect(() => {
    load();
  }, [load]);

  const filtered = entries.filter((e) => {
    if (!search.trim()) return true;
    const name = e.medicineId?.medicineName || "";
    return name.toLowerCase().includes(search.toLowerCase());
  });

  return (
    <div className="space-y-8 text-foreground">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <h1 className="text-2xl font-bold">Transactions</h1>
        <div className="flex flex-col xs:flex-row gap-2 w-full sm:w-auto">
          {role === "super_admin" && (
            <div className="flex items-center gap-2">
              <span className="text-sm text-muted-foreground">Pharmacy</span>
              <select
                value={pharmacyId}
                onChange={(e) => setPharmacyId(e.target.value)}
                className="px-3 py-2 rounded bg-background border border-border text-sm text-foreground"
              >
                {pharmacies.map((p) => (
                  <option key={p._id} value={p._id}>
                    {p.name}
                  </option>
                ))}
              </select>
            </div>
          )}
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Filter by medicine name"
            className="px-3 py-2 rounded bg-background border border-border text-sm text-foreground placeholder:text-muted-foreground flex-1 focus:outline-none focus:ring-2 focus:ring-primary"
          />
          <button
            onClick={load}
            className="px-4 py-2 rounded bg-muted hover:bg-muted/80 border border-border text-sm text-foreground transition-colors"
          >
            Reload
          </button>
        </div>
      </div>
      <div className="bg-card rounded-xl border border-border shadow-sm">
        {loading ? (
          <div className="p-6 text-muted-foreground text-sm">Loading...</div>
        ) : filtered.length === 0 ? (
          <div className="p-6 text-muted-foreground text-sm">
            No transactions
          </div>
        ) : (
          <>
            {/* Mobile / small screen cards */}
            <div className="md:hidden divide-y divide-border">
              {filtered.map((h) => {
                const dt = new Date(h.createdAt);
                return (
                  <div key={h._id} className="p-4 space-y-2">
                    <div className="flex flex-wrap items-baseline justify-between gap-2">
                      <p className="text-foreground text-sm font-medium">
                        {h.medicineName || h.medicineId?.medicineName || "-"}
                      </p>
                      <span className="text-[11px] text-muted-foreground">
                        {dt.toLocaleDateString()} {dt.toLocaleTimeString()}
                      </span>
                    </div>
                    <div className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-muted-foreground">
                      <span className="inline-flex items-center gap-1">
                        <span className="text-muted-foreground">Type:</span>
                        {h.transactionType}
                      </span>
                      <span className="inline-flex items-center gap-1">
                        <span className="text-muted-foreground">Qty:</span>
                        {h.quantity}
                      </span>
                      <span className="inline-flex items-center gap-1">
                        <span className="text-muted-foreground">Loc:</span>
                        {h.locationName || h.locationId?.name || "-"}
                      </span>
                    </div>
                    <div className="text-[11px] text-muted-foreground break-words leading-snug">
                      {h.sourceDocType}
                      {h.sourceDocId ? `: ${h.sourceDocId}` : ""}{" "}
                      {h.createdByUserId
                        ? `• ${
                            h.createdByUserId.role === "admin"
                              ? "admin"
                              : h.createdByUserId.username || "user"
                          }`
                        : ""}
                    </div>
                  </div>
                );
              })}
            </div>
            {/* Desktop table */}
            <div className="overflow-x-auto hidden md:block">
              <table className="w-full text-xs md:text-sm">
                <thead>
                  <tr className="text-left text-muted-foreground bg-muted/50">
                    <th className="py-2 pr-3 pl-5">Date</th>
                    <th className="py-2 pr-3">Medicine</th>
                    <th className="py-2 pr-3">Type</th>
                    <th className="py-2 pr-3">Qty</th>
                    <th className="py-2 pr-3">Location</th>
                    <th className="py-2 pr-3">Ref</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border text-foreground">
                  {filtered.map((h) => {
                    const dt = new Date(h.createdAt);
                    const datePart = dt.toLocaleDateString();
                    const timePart = dt.toLocaleTimeString();
                    return (
                      <tr key={h._id} className="align-top">
                        <td className="py-1.5 pr-3 pl-5 whitespace-pre-line leading-tight">
                          {datePart}\n{timePart}
                        </td>
                        <td className="py-1.5 pr-3">
                          {h.medicineName || h.medicineId?.medicineName || "-"}
                        </td>
                        <td className="py-1.5 pr-3">{h.transactionType}</td>
                        <td className="py-1.5 pr-3">{h.quantity}</td>
                        <td className="py-1.5 pr-3">
                          {h.locationName || h.locationId?.name || "-"}
                        </td>
                        <td className="py-1.5 pr-3 leading-tight text-xs md:text-[13px] text-muted-foreground">
                          {h.sourceDocType}
                          {h.sourceDocId ? `: ${h.sourceDocId}` : ""}{" "}
                          {h.createdByUserId
                            ? `• ${
                                h.createdByUserId.role === "admin"
                                  ? "admin"
                                  : h.createdByUserId.username || "user"
                              }`
                            : ""}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminTransactions;
